(function(THREE) {
  let cachedGeo = null;
  function b64ToFloat32(b64) {
    const bin = atob(b64);
    const len = bin.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) bytes[i] = bin.charCodeAt(i);
    return new Float32Array(bytes.buffer);
  }
  window.createDragonSlayer = function() {
    if (!cachedGeo) {
      cachedGeo = new THREE.BufferGeometry();
      const pos = b64ToFloat32("");
      const col = b64ToFloat32("");
      const norm = b64ToFloat32("");
      // Convert linear GLB vertex colors to sRGB for vibrant display in Three.js r128
      for (let i = 0; i < col.length; i++) {
        col[i] = Math.pow(Math.max(0, col[i]), 1 / 2.2);
      }
      cachedGeo.setAttribute("position", new THREE.BufferAttribute(pos, 3));
      cachedGeo.setAttribute("color", new THREE.BufferAttribute(col, 3));
      cachedGeo.setAttribute("normal", new THREE.BufferAttribute(norm, 3));
      cachedGeo.computeBoundingBox();
    }
    const mat = new THREE.MeshStandardMaterial({
      vertexColors: true,
      flatShading: true,
      roughness: 0.72,
      metalness: 0.08
    });
    const mesh = new THREE.Mesh(cachedGeo, mat);
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    const group = new THREE.Group();
    group.add(mesh);
    return group;
  };
})(window.THREE);
